/// A mission, as cortext's mission registry stores it: one governed object per
/// mission, homed in the `.models` system directory beside `ModelManifest` and
/// `OntologyDeclaration` (the same governed-object recipe), with an ACL the
/// owner controls and the platform's own revision history.
///
/// The object is a *reference*, like the other two: the mission document is a
/// Drive file named here by id, content revision and sha256, and the fields a
/// reader queries on (city, status, objectives, KPIs, variants, bindings) are
/// projected once per source revision into the `missions` registry
/// (registry.fbs), so nothing on a read path opens the document. The document
/// is JSON — it is cortext's own rendering of the mission, not an authored
/// file — while `spec` names the `mission.yaml` a person dropped, kept as
/// provenance the way an ontology keeps its bronze file.
///
/// The mission document holds only asserted state. What a mission has *done*
/// (its messages, decisions, runs and the activity line derived from them) is
/// not here and does not revise the object: a revision is a change to what the
/// mission *is*, which is what makes the chain readable as a history of
/// decisions rather than of chatter.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Mission {
    /// The principal whose write this revision is (oid).
    pub authored_by: Option<String>,
    /// The decision, approval or drop this revision records, empty for an
    /// ordinary write: what a revisions read filters on to answer "the
    /// decision points" rather than "every write".
    pub checkpoint: Option<String>,
    /// The Drive file object holding the mission document (JSON).
    pub document: ObjectId,
    /// That file's content revision at this write.
    pub document_cid: Option<ContentId>,
    /// sha256 (hex) of the document bytes; the projector verifies it.
    pub document_sha256: String,
    /// The authored mission id, permanent and unique; the object id derives
    /// from it, so a re-drop of the same spec revises the same object.
    pub mission_id: String,
    /// The `mission.yaml` a person dropped, as provenance; absent for a
    /// mission created through the API.
    pub spec: Option<ObjectId>,
    /// That file's content revision at registration.
    pub spec_cid: Option<ContentId>,
}

impl Mission {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsMission<'a>> {
        use crate::types::generated::mission_generated::MissionBuilder as FbsMissionBuilder;

        let authored_by_offset = self.authored_by.as_ref().map(|s| builder.create_string(s));
        let checkpoint_offset = self.checkpoint.as_ref().map(|s| builder.create_string(s));
        let document_offset = self.document.serialize_to(builder);
        let document_cid_offset = self.document_cid.as_ref().map(|o| o.serialize_to(builder));
        let document_sha256_offset = builder.create_string(&self.document_sha256);
        let mission_id_offset = builder.create_string(&self.mission_id);
        let spec_offset = self.spec.as_ref().map(|o| o.serialize_to(builder));
        let spec_cid_offset = self.spec_cid.as_ref().map(|o| o.serialize_to(builder));

        let mut bldr = FbsMissionBuilder::new(builder);
        if let Some(offset) = authored_by_offset {
            bldr.add_authored_by(offset);
        }
        if let Some(offset) = checkpoint_offset {
            bldr.add_checkpoint(offset);
        }
        bldr.add_document(document_offset);
        if let Some(offset) = document_cid_offset {
            bldr.add_document_cid(offset);
        }
        bldr.add_document_sha256(document_sha256_offset);
        bldr.add_mission_id(mission_id_offset);
        if let Some(offset) = spec_offset {
            bldr.add_spec(offset);
        }
        if let Some(offset) = spec_cid_offset {
            bldr.add_spec_cid(offset);
        }
        bldr.finish()
    }
}

impl From<FbsMission<'_>> for Mission {
    fn from(fbs: FbsMission<'_>) -> Self {
        let authored_by = fbs.authored_by().map(ToOwned::to_owned);
        let checkpoint = fbs.checkpoint().map(ToOwned::to_owned);
        let document = ObjectId::from(fbs.document());
        let document_cid = fbs.document_cid().map(ContentId::from);
        let document_sha256 = fbs.document_sha256().to_owned();
        let mission_id = fbs.mission_id().to_owned();
        let spec = fbs.spec().map(ObjectId::from);
        let spec_cid = fbs.spec_cid().map(ContentId::from);
        Self {
            authored_by,
            checkpoint,
            document,
            document_cid,
            document_sha256,
            mission_id,
            spec,
            spec_cid,
        }
    }
}

impl crate::FbsSerde for Mission {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsMission>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

